static int ccp_sha_import ( struct ahash_request * req , const void * in ) { struct ccp_sha_req_ctx * rctx = ahash_request_ctx_dma ( req ) ; struct ccp_sha_exp_ctx state ; memcpy ( & state , in , sizeof ( state ) ) ; rctx -> type = state . type ; rctx -> msg_bits = state . msg_bits ; rctx -> first = state . first ; memcpy ( rctx -> ctx , state . ctx , sizeof ( rctx -> ctx ) ) ; rctx -> buf_count = state . buf_count ; memcpy ( rctx -> buf , state . buf , sizeof ( rctx -> buf ) ) ; return 0 ; } 